mapper.select:
select id, title, slug, summary, cover_url, tags, author_id, author_name,
       null as content_html, null as content_markdown, null as content_json, status, visibility, is_paid,
       seo_title, seo_description, seo_keywords, canonical_url, published_at,
       wechat_media_id, wechat_account_id, create_by, create_time, update_by, update_time, remark, del_flag
from content_article
where del_flag = '0'

    and title like concat('%', #{title}, '%')


    and slug = #{slug}


    and status = #{status}


    and visibility = #{visibility}


    and tags like concat('%', #{tags}, '%')


    and published_at >= #{beginPublishedAt}


    and published_at <= #{endPublishedAt}

order by update_time desc, id desc
